function demoId($table,$column,$value){$row=dbFetchOne("SELECT id FROM $table WHERE $column=:value LIMIT 1",['value'=>$value]);return$row?(int)$row['id']:null;}
function demoUser($name,$email,$role,$password,$agencyIds){$id=demoId('users','email_normalized',$email);if(!$id){dbExecute('INSERT INTO users(fullname,email,email_normalized,phone,password_hash,role,status,password_changed_at)VALUES(:name,:email,:email2,\'0600000000\',:hash,:role,\'active\',NOW())',['name'=>$name,'email'=>$email,'email2'=>$email,'hash'=>password_hash($password,PASSWORD_DEFAULT),'role'=>$role]);$id=(int)db()->lastInsertId();}foreach($agencyIds as $index=>$agency)dbExecute('INSERT IGNORE INTO user_agencies(user_id,agency_id,is_primary,created_by)VALUES(:user,:agency,:primary,NULL)',['user'=>$id,'agency'=>$agency,'primary'=>$index===0?1:0]);return$id;}

