    $active=(int)dbFetchOne("SELECT id FROM reservations WHERE reference='DEMO-ACTIVE'")['id'];if(!dbFetchOne('SELECT id FROM rental_contracts WHERE reservation_id=:id',['id'=>$active])){dbExecute("INSERT INTO rental_contracts(reservation_id,contract_number,status,current_version,signed_at,activated_at,created_by)VALUES(:reservation,'DEMO-CTR-001','active',1,NOW(),NOW(),:user)",['reservation'=>$active,'user'=>$agent]);$contract=(int)db()->lastInsertId();dbExecute("INSERT INTO contract_versions(contract_id,version_number,language_code,snapshot_json,terms_text,change_reason,created_by)VALUES(:contract,1,'fr','{\"demo\":true}','Demo rental contract terms','Initial demo contract',:user)",['contract'=>$contract,'user'=>$agent]);dbExecute("INSERT INTO payments(agency_id,reservation_id,contract_id,payment_number,amount,currency,paid_at,method,status,created_by)VALUES(:agency,:reservation,:contract,'DEMO-PAY-001',2600,'MAD',NOW(),'card','paid',:user)",['agency'=>$aga,'reservation'=>$active,'contract'=>$contract,'user'=>$agent]);dbExecute("INSERT INTO deposits(reservation_id,contract_id,amount,currency,status,received_at,created_by)VALUES(:reservation,:contract,7000,'MAD','held',NOW(),:user)",['reservation'=>$active,'contract'=>$contract,'user'=>$agent]);dbExecute("INSERT INTO invoices(agency_id,customer_id,reservation_id,contract_id,invoice_number,status,currency,subtotal,total_amount,paid_amount,issued_at,created_by)VALUES(:agency,:customer,:reservation,:contract,'DEMO-INV-001','paid','MAD',2600,2600,2600,NOW(),:user)",['agency'=>$aga,'customer'=>$youssef,'reservation'=>$active,'contract'=>$contract,'user'=>$agent]);dbExecute("INSERT INTO vehicle_inspections(contract_id,vehicle_id,customer_id,inspection_type,inspected_at,mileage,fuel_level,cleanliness,status,validated_at,created_by)VALUES(:contract,:vehicle,:customer,'checkout',DATE_SUB(NOW(),INTERVAL 2 DAY),25000,100,'clean','validated',NOW(),:user)",['contract'=>$contract,'vehicle'=>$duster,'customer'=>$youssef,'user'=>$